u.E("ev-legge-costituzionale-n-2-1963",1963,"9 febbraio 1963","Legge costituzionale n. 2/1963","Parifica a cinque anni la durata delle due Camere: prima il Senato durava sei anni.","legge","senato camera-dei-deputati",71,71)
u.E("ev-nomine-senatori-a-vita-pertini",1984,"1984","Pertini nomina senatori a vita oltre il numero di cinque","Il Presidente Pertini nomina altri due senatori a vita seguendo la tesi dei cinque per ciascun Presidente; oggi il limite è complessivo.","politica","senatori-a-vita",66,66)
u.E("ev-leggi-elettorali-1993",1993,"1993","Leggi elettorali del 1993 e legge sulla campagna elettorale","Si passa a un sistema in prevalenza maggioritario; il d.lgs. n. 533/1993 è il testo unico del Senato e la legge n. 515/1993 disciplina le campagne elettorali.","legge","sistema-maggioritario par-condicio",69,70)
u.E("ev-legge-costituzionale-n-1-2000",2000,"17 gennaio 2000","Legge costituzionale n. 1/2000: circoscrizione Estero","Modifica l'art. 48 e istituisce la circoscrizione Estero per il voto degli italiani residenti all'estero.","legge","circoscrizione-estero elettorato-attivo",67,67)
u.E("ev-legge-par-condicio",2000,"22 febbraio 2000","Legge n. 28/2000 sulla par condicio","Disciplina la parità di accesso ai mezzi di informazione durante le campagne elettorali.","legge","par-condicio",70,70)
u.E("ev-legge-costituzionale-n-1-2001",2001,"23 gennaio 2001","Legge costituzionale n. 1/2001: seggi della circoscrizione Estero","Assegna alla circoscrizione Estero 12 deputati e 6 senatori (oggi 8 e 4); la legge n. 459/2001 ne dà attuazione.","legge","circoscrizione-estero",67,67)
u.E("ev-legge-270-2005",2005,"21 dicembre 2005","Legge elettorale n. 270/2005","Reintroduce il proporzionale con premio di maggioranza e liste bloccate; sarà dichiarata in parte illegittima nel 2014.","legge","sistema-proporzionale premio-di-maggioranza soglia-di-sbarramento",69,71)
u.E("ev-scioglimento-camere-2008",2008,"6 febbraio 2008","Scioglimento anticipato delle Camere","Lo scioglimento fa rinviare al 2009 i tre referendum sulla legge elettorale.","politica","procedimento-elettorale",69,69)
u.E("ev-referendum-elettorali-2009",2009,"21 giugno 2009","Referendum sulla legge elettorale senza quorum","I tre quesiti sulla legge n. 270/2005 non raggiungono il quorum di partecipazione.","politica","premio-di-maggioranza sistema-elettorale",69,69)
u.E("ev-incandidabilita-2012",2012,"31 dicembre 2012","Incandidabilità alle elezioni politiche","Il decreto legislativo n. 235/2012 estende l'incandidabilità a deputati e senatori.","legge","incandidabilita",73,74)
u.E("ev-sentenza-1-2014",2014,"13 gennaio 2014","Sentenza n. 1/2014 sulla legge elettorale","La Corte costituzionale dichiara illegittimi il premio di maggioranza senza soglia e le liste bloccate della legge n. 270/2005.","giurisprudenza","premio-di-maggioranza sistema-elettorale",69,71)
u.E("ev-referendum-sulla-riduzione-dei-parlamentari",2020,"20–21 settembre 2020","Referendum sulla riduzione dei parlamentari","Il corpo elettorale conferma la legge costituzionale n. 1/2020: 400 deputati e 200 senatori elettivi.","politica","camera-dei-deputati senato",71,72)
u.E("ev-voto-diciottenni-senato",2021,"18 ottobre 2021","Legge costituzionale n. 1/2021: voto a 18 anni per il Senato","Elimina il requisito dei 25 anni per eleggere i senatori.","legge","elettorato-attivo senato",67,67)
u.E("ev-legge-elettorale-2026",2026,"24 ottobre 2026","Entrata in vigore della legge elettorale n. 180/2026","Sistema proporzionale con eventuale premio di governabilità, soglie e preferenze.","legge","sistema-elettorale premio-di-maggioranza soglia-di-sbarramento",69,71)

