 ("Sistemi elettorali","sistema-elettorale",[("Maggioritario","sistema-maggioritario","#stabilità"),("Proporzionale","sistema-proporzionale","#rappresentatività"),("Correttivi",[("Premio","premio-di-maggioranza"),("Soglie","soglia-di-sbarramento")]),("Legge n. 180/2026","#vigente dal 24 ottobre 2026")]),
